const express = require('express');
const bodyParser = require('body-parser');
const csurf = require('csurf');

const app = express();
app.use(bodyParser.urlencoded({ extended: false }));
app.set('view engine', 'ejs');

// Configure CSRF middleware
const csrfMiddleware = csurf({ cookie: true });
app.use(csrfMiddleware);
app.use((req, res, next) => {
  // Make the CSRF token available to all views
  res.locals.csrfToken = req.csrfToken();
  next();
});

// Serve the form on the homepage
app.get('/', (req, res) => {
  res.render('index');
});

// Handle form submissions
app.post('/transferFunds', csrfMiddleware, (req, res) => {
  const { fromAccount, toAccount, amount } = req.body;

  // Server-side validation and sanitization
  if (
    !/^[0-9]{6,12}$/.test(fromAccount) ||
    !/^[0-9]{6,12}$/.test(toAccount) ||
    parseFloat(amount) <= 0 ||
    isNaN(parseFloat(amount))
  ) {
    return res.status(400).render('index', { error: 'Invalid input data.' });
  }

  // Process the transfer
  console.log(`Transfer from ${fromAccount} to ${toAccount}: $${amount}`);

  res.render('success');
});

// Start the server
app.listen(3000, () => {
  console.log('Server started on port 3000');
});
